FILE *f = fopen("/proc/self/status", "r");
char line[256];
while (f && fgets(line, sizeof(line), f)) {
    if (strncmp(line, "TracerPid:", 10) == 0 && atoi(line + 10) != 0) {
        abort(); // Depurador detectado
    }
}

